package co.aplomo.web;
import co.aplomo.soporte.*;import co.aplomo.dao.*;import co.aplomo.db.*;import co.aplomo.modelo.*;import co.aplomo.servicio.*;import co.aplomo.seguridad.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.*;import org.junit.jupiter.params.provider.*;import java.util.*;import java.time.*;import java.io.*;import javax.imageio.ImageIO;import static org.junit.jupiter.api.Assertions.*;
/** Paso 24, RF-002/003/024/033: ataques por ID y transacciones sin confirmar. */
class HttpTresRolesTest extends HttpPrueba {
 EscenarioConsultas e;int ev1,ev2;Usuarios us;CuentaEmpresaDao ce=new CuentaEmpresaDao();
 @BeforeEach void escenario()throws Exception{e=new EscenarioConsultas(this,carpetaFotos);us=servicioUsuarios();ev1=crear(Cuenta.Rol.EVALUADOR,List.of(empresa));ev2=crear(Cuenta.Rol.EVALUADOR,List.of(e.empresaB));entrar(ev1);}
 void cambiarCuenta(int id)throws Exception{post("/logout",Map.of("csrf",csrf(get("/"))));entrar(id);}
 int crear(Cuenta.Rol rol,List<Integer> empresas)throws Exception{int id=us.crear(cuenta(admin),new Usuarios.Datos("Persona "+UUID.randomUUID(),UUID.randomUUID()+"@prueba.invalid","123","Pruebas",rol,null,empresas),clave);dao.contrasena(con,id,cuenta(id).hash(),false);return id;}
 @ParameterizedTest @ValueSource(strings={"empresas","reservas","visitas","evaluaciones","pendientes","sugerencias","puestos"})
 void listasSoloMuestranEmpresasAsignadas(String ruta)throws Exception{var h=get("/"+ruta);assertEquals(200,h.statusCode());assertFalse(h.body().contains("Empresa ajena QA"));assertEquals(403,get("/"+ruta+"?empresa="+e.empresaB).statusCode());}
 @Test void detallesFotosInformeYPostAjenosEstanBloqueados()throws Exception{
  int foto=new EvaluacionDao().fotos(con,e.evalB).get(0).id();for(String ruta:List.of("/empresas/"+e.empresaB,"/sedes/"+e.sedeB,"/salones/"+e.salonB,"/puestos/"+e.puestoB,"/reservas/"+e.reservaB,"/visitas/"+e.visitaB,"/evaluaciones/"+e.evalB,"/fotos/"+foto,"/pendientes/"+e.pendienteB,"/sugerencias/"+e.sugerenciaB,"/informes/empresa/"+e.empresaB))assertEquals(403,get(ruta).statusCode(),ruta);
  String csrf=csrf(get("/"));assertEquals(403,post("/reservas/"+e.reservaB+"/cancelar",Map.of("csrf",csrf,"motivo","No permitido")).statusCode());assertThrows(SecurityException.class,()->e.evaluaciones.analisis().autorizarParcial(cuenta(ev1),e.visitaB));
 }
 @Test void evaluadorNoAdministraEmpresasEstadosNiCuentas()throws Exception{String csrf=csrf(get("/"));for(String ruta:List.of("/usuarios","/usuarios/nuevo","/empresas/nueva"))assertEquals(403,get(ruta).statusCode(),ruta);for(String ruta:List.of("/usuarios","/empresas/"+empresa+"/desactivar","/puestos/"+e.puesto1+"/desactivar"))assertEquals(403,post(ruta,Map.of("csrf",csrf)).statusCode(),ruta);var em=new Empresas(tx);assertThrows(SecurityException.class,()->em.estadoEmpresa(cuenta(ev1),empresa,false));assertThrows(SecurityException.class,()->em.guardar(cuenta(ev1),new Empresa(0,ev1,"No permitida","OTRA","",null,null,null,true)));assertFalse(get("/empresas/"+empresa).body().contains("/desactivar"));}
 @Test void evaluadorCreaSedePuestoReservaYEvaluacion()throws Exception{var em=new Empresas(tx);int sede=em.guardar(cuenta(ev1),new Sede(0,empresa,"Nueva sede E","Calle 1","Armenia","123","8 a 5","Prueba",true)).id();int salon=em.guardar(cuenta(ev1),new Salon(0,sede,"Sala E","Prueba",1,5,true)).id();int puesto=em.guardar(cuenta(ev1),new Puesto(0,salon,null,null,1,"Puesto E","MESA","Centro",null,true)).id();var res=new Reservas(tx,reloj);int id=res.guardar(cuenta(ev1),0,new Reservas.Datos(empresa,sede,salon,LocalDate.now(reloj),LocalTime.of(18,0),LocalTime.of(19,0),"EVALUACION_INICIAL","Prueba",""));res.aceptar(cuenta(ev1),id);int visita=new Visitas(tx,reloj).iniciar(cuenta(ev1),id);int evaluacion=evaluar(visita,puesto);assertEquals(1,e.evaluaciones.analisis().listar(cuenta(ev1),evaluacion).size());assertEquals(cuenta(ev1).nombre(),new EvaluacionDao().consultar(con,evaluacion).responsable());int cancelar=res.guardar(cuenta(ev1),0,new Reservas.Datos(empresa,sede,salon,LocalDate.now(reloj),LocalTime.of(20,0),LocalTime.of(21,0),"SEGUIMIENTO","Prueba",""));res.cancelar(cuenta(ev1),cancelar,"Prueba cancelada");assertEquals("CANCELADA",res.consultar(cuenta(ev1),cancelar).reserva().estado());}
 int evaluar(int visita,int puesto)throws Exception{var bytes=new ByteArrayOutputStream();ImageIO.write(new java.awt.image.BufferedImage(12,12,1),"png",bytes);return e.evaluaciones.guardar(cuenta(ev1),visita,new Evaluaciones.Datos(puesto,"Postura E","MAS_INADECUADA","",120,false,false,false,false,false,false,"",true,false),List.of(new Fotos.Entrada(bytes.toByteArray(),"PERFIL","Prueba")),List.of(new Analisis.Solicitud(0,CasosRulaPrueba.todos().get(0).entrada())));}
 @Test void retirarAsignacionRevocaSiguientePeticionYConservaHistoriaPropia()throws Exception{int propia=evaluar(e.visitaAbierta,e.puesto2);var datos=new Usuarios.Datos(cuenta(ev1).nombre(),cuenta(ev1).correo(),"123","Pruebas",Cuenta.Rol.EVALUADOR,null,List.of());us.editar(cuenta(admin),ev1,datos,"");assertEquals(403,get("/empresas/"+empresa).statusCode());assertEquals(200,get("/evaluaciones/"+propia).statusCode());assertFalse(get("/evaluaciones/"+propia).body().contains("/analizar"));assertThrows(SecurityException.class,()->e.evaluaciones.analisis().autorizarParcial(cuenta(ev1),e.visitaAbierta));String h=get("/mis-evaluaciones").body();assertTrue(h.contains("Ya no asignada"));assertEquals(List.of(e.puesto2),e.consultas.propias(cuenta(ev1),Map.of()).catalogos().get("puesto").stream().map(co.aplomo.dao.ConsultaDao.Opcion::id).toList());assertTrue(get("/").body().contains("Aún no tienes empresas asignadas. Pídeselas al Administrador."));assertTrue(h.contains("/evaluaciones/"+propia));assertFalse(h.contains("/evaluaciones/"+e.evalRojo+"\""));assertTrue(Sql.<Integer>uno(con,"SELECT COUNT(*) FROM bitacora WHERE tabla='cuenta_empresa' AND accion='DESACTIVAR' AND id_cuenta=?",r->r.getInt(1),admin)>0);}
 @Test void unSoloEvaluadorActivoYUsuarioDeVariasEmpresas()throws Exception{var error=assertThrows(IllegalArgumentException.class,()->crear(Cuenta.Rol.EVALUADOR,List.of(empresa)));assertTrue(error.getMessage().startsWith("Esta empresa ya tiene evaluador:"));int u=crear(Cuenta.Rol.USUARIO,List.of(empresa,e.empresaB));cambiarCuenta(u);String h=get("/empresas").body();assertTrue(h.contains("Empresa ajena QA"));assertEquals(403,get("/agenda").statusCode());assertEquals(403,get("/evaluaciones/"+e.evalAbierta).statusCode());assertEquals(200,get("/evaluaciones/"+e.evalB).statusCode());assertEquals(403,get("/fotos/"+new EvaluacionDao().fotos(con,e.evalB).get(0).id()).statusCode());assertEquals(List.of(empresa,e.empresaB),ce.ids(con,u));}
 @Test void notasConPermisosCsrfYAcuseRenovado()throws Exception{var ag=new Reservas(tx,reloj).agenda();ag.guardarNota(cuenta(admin),e.reservaAbierta,"<script>No ejecutar</script>");String h=get("/reservas/"+e.reservaAbierta).body();assertTrue(h.contains("&lt;script&gt;No ejecutar&lt;/script&gt;"));assertTrue(h.contains(">Entendido</button>"));assertEquals(403,post("/reservas/"+e.reservaAbierta+"/entendido",Map.of()).statusCode());assertEquals(303,post("/reservas/"+e.reservaAbierta+"/entendido",Map.of("csrf",csrf(get("/")))).statusCode());assertTrue(ag.nota(cuenta(ev1),e.reservaAbierta).vista());ag.guardarNota(cuenta(admin),e.reservaAbierta,"Nueva nota");assertFalse(ag.nota(cuenta(ev1),e.reservaAbierta).vista());assertTrue(ag.nuevas(cuenta(ev1)).contains(e.reservaAbierta));assertThrows(SecurityException.class,()->ag.entender(cuenta(ev2),e.reservaAbierta));assertThrows(SecurityException.class,()->ag.guardarNota(cuenta(ev1),e.reservaAbierta,"No"));cambiarCuenta(usuario);assertFalse(get("/reservas/"+e.reservaAbierta).body().contains("Nueva nota"));assertThrows(IllegalArgumentException.class,()->ag.guardarNota(cuenta(admin),e.reservaAbierta,"x".repeat(501)));}
 @Test void agendaSoloLecturaAdminYFiltroInactivo()throws Exception{cambiarCuenta(admin);var ag=new Reservas(tx,reloj).agenda();String h=get("/agenda?fecha=2026-11-11").body();assertFalse(h.contains("Nueva reserva"));assertTrue(h.contains("Empresa ajena QA"));dao.acceso(con,ev2,0,null,Cuenta.Estado.INACTIVA);assertTrue(get("/agenda").body().contains("(inactivo)"));assertEquals(400,get("/agenda?evaluador=99999999").statusCode());assertTrue(ag.nuevas(cuenta(usuario)).isEmpty());}
 @Test void agendaFechasBordesCanceladasCrucesYSeisSemanas()throws Exception{var ag=new Reservas(tx,reloj).agenda();var v=ag.consultar(cuenta(ev1),Map.of("fecha","2026-11-11"));assertEquals(DayOfWeek.MONDAY,v.desde().getDayOfWeek());assertTrue(v.citas().stream().noneMatch(c->c.ficha().reserva().id()==e.reservaB||c.ficha().reserva().id()==e.reservaCancelada));assertTrue(ag.consultar(cuenta(ev1),Map.of("fecha","2026-11-11","canceladas","1")).citas().stream().anyMatch(c->c.ficha().reserva().id()==e.reservaCancelada));assertEquals(LocalDate.of(2026,12,28),ag.consultar(cuenta(ev1),Map.of("fecha","2027-01-01")).desde());assertFalse(ag.consultar(cuenta(ev1),Map.of("vista","no","fecha","mal")).mes());var mes=ag.consultar(cuenta(ev1),Map.of("vista","mes","fecha","2026-08-01"));assertEquals(42,PaginasAgenda.pagina(new Sesiones(reloj).crear(cuenta(ev1)),mes).split("agenda-dia",-1).length-1);Sql.actualizar(con,"UPDATE reserva SET hora_inicio='11:30:00',hora_fin='12:30:00' WHERE id_reserva=?",e.reservaEsperando);assertEquals(2,ag.consultar(cuenta(ev1),Map.of("fecha","2026-11-11")).citas().stream().filter(Agenda.Cita::cruce).count());}
 @Test void practicaPrivadaPorEvaluador()throws Exception{var p=new Visitas(tx,reloj).practica();var a=p.abrir(cuenta(ev1),"PLANTA");var b=p.abrir(cuenta(ev2),"OFICINA");assertNotEquals(a.visita(),b.visita());assertEquals(a.visita(),p.enCurso(cuenta(ev1)));assertThrows(SecurityException.class,()->e.evaluaciones.contexto(cuenta(ev1),b.visita()));assertNotNull(e.evaluaciones.contexto(cuenta(ev1),a.visita()));assertTrue(e.consultas.propias(cuenta(ev1),Map.of()).filas().isEmpty());}
 @Test void cambiosDeRolConservanCampoAnteriorYRetiranAsignaciones()throws Exception{Integer antes=cuenta(usuario).empresa();us.editar(cuenta(admin),usuario,new Usuarios.Datos("Usuario convertido",cuenta(usuario).correo(),"123","Pruebas",Cuenta.Rol.ADMINISTRADOR,null),"");assertEquals(antes,cuenta(usuario).empresa());assertTrue(ce.ids(con,usuario).isEmpty());}
 @Test void arranqueCompruebaEsquemaActual()throws Exception{assertDoesNotThrow(()->Esquema.verificar(con));assertEquals(22,Sql.<Integer>uno(con,"SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",rs->rs.getInt(1)));}
 @Test void evaluadorAbreFotosYCalculoParcialConElMismoContratoYAjenaNo()throws Exception{
  assertEquals(200,get("/evaluaciones/"+e.evalAbierta).statusCode());int foto=new EvaluacionDao().fotos(con,e.evalAbierta).get(0).id();assertEquals(200,get("/fotos/"+foto).statusCode());String token=csrf(get("/"));assertEquals(403,post("/evaluaciones/calcular",Map.of("csrf",token,"visita",""+e.visitaB,"segmento","BRAZO","angulo","0")).statusCode());assertEquals(200,get("/evaluaciones/nueva?visita="+e.visitaAbierta+"&puesto="+e.puesto2).statusCode());assertFalse(get("/agenda").body().contains("aria-label=\"Atrás\""));assertFalse(get("/mis-evaluaciones").body().contains("aria-label=\"Atrás\""));
 }
 @Test void historialPropioOrdenaEmpatesPorIdDescendenteYUsaPrimerAutor()throws Exception{int primero=evaluar(e.visitaAbierta,e.puesto2),segundo=evaluar(e.visitaAbierta,e.puesto2);var filas=e.consultas.propias(cuenta(ev1),Map.of()).filas();assertEquals(List.of(segundo,primero),filas.stream().map(co.aplomo.dao.ConsultaDao.Fila::id).toList());new BitacoraDao().registrar(con,ev2,java.time.LocalDateTime.now(reloj),"evaluacion",primero,"CREAR",null,null,"Registro posterior de QA");assertFalse(AccesoDatos.propia(con,cuenta(ev2),primero));}
 @Test void empresaInactivaDejaHistoriaPropiaEnSoloLectura()throws Exception{int id=evaluar(e.visitaAbierta,e.puesto2);new Empresas(tx).estadoEmpresa(cuenta(admin),empresa,false);assertEquals(200,get("/evaluaciones/"+id).statusCode());assertFalse(e.evaluaciones.consultar(cuenta(ev1),id).enCurso());assertFalse(e.evaluaciones.permiteTrabajo(cuenta(ev1),id));assertThrows(SecurityException.class,()->e.evaluaciones.analisis().guardar(cuenta(ev1),id,List.of(new Analisis.Solicitud(new EvaluacionDao().fotos(con,id).get(0).id(),CasosRulaPrueba.todos().get(0).entrada()))));}
 @Test void agendaPrefiereEvaluadorActivoCuandoOtroAsignadoEstaInactivo()throws Exception{dao.acceso(con,ev1,0,null,Cuenta.Estado.INACTIVA);int nuevo=crear(Cuenta.Rol.EVALUADOR,List.of(empresa));var agenda=new Reservas(tx,reloj).agenda().consultar(cuenta(nuevo),Map.of("fecha","2026-11-11"));assertTrue(agenda.citas().stream().allMatch(c->Objects.equals(c.evaluador(),nuevo)));}
}
